    LEFT JOIN f360.inventory_balances b ON b.variant_id = x.v AND b.location_id = x.l WHERE coalesce(b.on_hand, 0) <> x.q;
  IF bad > 0 THEN RAISE EXCEPTION 'D1: % saldos no quedaron iguales a los de staging', bad; END IF;
END $c$;
SELECT jsonb_build_object('total_pares', (SELECT sum(on_hand) FROM f360.inventory_balances),
  'por_ubicacion', (SELECT jsonb_object_agg(l.name, s.q) FROM (SELECT location_id, sum(on_hand) q FROM f360.inventory_balances GROUP BY 1) s JOIN f360.locations l ON l.id = s.location_id),
  'modelos', (SELECT count(*) FROM f360.products), 'variantes', (SELECT count(*) FROM f360.product_variants), 'fotos', (SELECT count(*) FROM f360.product_media));
COMMIT;
